files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --border: #0f3460;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image:
    linear-gradient(45deg, var(--border) 25%, transparent 25%),
    linear-gradient(-45deg, var(--border) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, var(--border) 75%),
    linear-gradient(-45deg, transparent 75%, var(--border) 75%);
  background-size: 32px 32px;
  background-position: 0 0, 0 16px, 16px -16px, -16px 0;
  font-family: ui-monospace, 'Courier New', monospace;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--accent);
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
}

.title {
  font-size: 20px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 16px;
}

.mode {
  font-size: 18px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 8px;
}

.countdown {
  font-size: clamp(48px, 14vw, 88px);
  font-weight: bold;
  letter-spacing: 4px;
  color: var(--text);
  margin: 16px 0 24px;
  text-shadow: 4px 4px 0 var(--border);
  line-height: 1;
}

.controls, .mode-switch {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.mode-switch { margin-top: 16px; }

.btn {
  font-family: inherit;
  font-size: 18px;
  padding: 12px 20px;
  background: var(--border);
  color: var(--text);
  border: 3px solid var(--accent);
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: transform 0.05s, background 0.15s;
}

.btn:hover { background: var(--accent); color: var(--bg); }
.btn:focus-visible { outline: 3px dashed var(--accent); outline-offset: 3px; }
.btn:active { transform: translate(2px, 2px); }

.btn.small { font-size: 14px; padding: 8px 12px; }
.btn.active { background: var(--accent); color: var(--bg); }

@media (max-width: 360px) {
  .card { padding: 24px 12px; }
  .btn { font-size: 16px; padding: 10px 14px; }
  .btn.small { font-size: 13px; padding: 8px 10px; }
}

const WORK_DURATION = 25 * 60;
const BREAK_DURATION = 5 * 60;

const countdownEl = document.getElementById('countdown');
const modeLabelEl = document.getElementById('modeLabel');
const startPauseBtn = document.getElementById('startPauseBtn');
const resetBtn = document.getElementById('resetBtn');
const workBtn = document.getElementById('workBtn');
const breakBtn = document.getElementById('breakBtn');

let currentMode = 'work';
let remaining = WORK_DURATION;
let timerId = null;
let isRunning = false;

function formatTime(seconds) {
  const m = Math.floor(seconds / 60).toString().padStart(2, '0');
  const s = (seconds % 60).toString().padStart(2, '0');
  return `${m}:${s}`;
}

function render() {
  countdownEl.textContent = formatTime(remaining);
  modeLabelEl.textContent = currentMode === 'work' ? 'Work' : 'Break';
  startPauseBtn.textContent = isRunning ? 'Pause' : 'Start';
  startPauseBtn.setAttribute('aria-label', isRunning ? 'Pause timer' : 'Start timer');
  workBtn.classList.toggle('active', currentMode === 'work');
  breakBtn.classList.toggle('active', currentMode === 'break');
  workBtn.setAttribute('aria-pressed', currentMode === 'work');
  breakBtn.setAttribute('aria-pressed', currentMode === 'break');
}

function stopTimer() {
  if (timerId) {
    clearInterval(timerId);
    timerId = null;
  }
  isRunning = false;
}

function tick() {
  remaining -= 1;
  if (remaining <= 0) {
    stopTimer();
    remaining = 0;
    render();
    switchMode(currentMode === 'work' ? 'break' : 'work');
    return;
  }
  render();
}

function startTimer() {
  if (isRunning) return;
  isRunning = true;
  timerId = setInterval(tick, 1000);
  render();
}

function pauseTimer() {
  stopTimer();
  render();
}

function resetTimer() {
  stopTimer();
  remaining = currentMode === 'work' ? WORK_DURATION : BREAK_DURATION;
  render();
}

function switchMode(mode) {
  currentMode = mode;
  stopTimer();
  remaining = mode === 'work' ? WORK_DURATION : BREAK_DURATION;
  render();
}

startPauseBtn.addEventListener('click', () => {
  if (isRunning) {
    pauseTimer();
  } else {
    startTimer();
  }
});

resetBtn.addEventListener('click', resetTimer);
workBtn.addEventListener('click', () => switchMode('work'));
breakBtn.addEventListener('click', () => switchMode('break'));

render();
